mapper.select:
SELECT CP.CpnId, CP.ChnlCode, CP.ProdCode, CP.Remark, CP.State,
       CP.RegistDate, CP.RegistId, CP.RegistName, CP.ChangeDate, CP.ChangeId, CP.ChangeName,
       PH.ProdName, PH.SalePrice, PH.SaleYn, PH.ImgUrl80
FROM shopion.tStrProdCpnProd CP
INNER JOIN shopion.tPrdProd PH ON CP.ProdCode = PH.ProdCode


        AND CP.CpnId = #{pCpnId}


        AND CP.ChnlCode = #{pChnlCode}


        AND PH.SaleYn = #{pSaleYn}


ORDER BY CP.ProdCode

mapper.insert:
INSERT INTO shopion.tStrProdCpnProd (
    CpnId, ChnlCode, ProdCode, Remark, State,
    RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
) VALUES (
    #{cpnId}, #{chnlCode}, #{prodCode}, #{remark}, #{state},
    #{registDate}, #{registId}, #{registName}, #{changeDate}, #{changeId}, #{changeName}
)

mapper.delete:
DELETE FROM shopion.tStrProdCpnProd
WHERE CpnId = #{pCpnId}

    AND ChnlCode = #{pChnlCode}


    AND ProdCode IN

        #{item}
